package forge.harnessenv.grader;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import forge.game.player.Player;
import forge.game.player.PlayerController;

/**
 * Counts the Forge-AI decision methods entered for a graded seat. The grader's patched copy of PlayerControllerAi
 * (generated by eval/harness_env/harness_env_aicount.py) calls {@link #enter} at the top of every decision hook; an entry counts
 * when the controller's player is one the grader watches. Without the patch on the classpath nothing calls it, and
 * {@link #patched} says so, so a report never reads a missing counter as zero.
 */
public final class AiCounter {
    private AiCounter() { }

    private static final Map<Player, List<String>> WATCHED = new ConcurrentHashMap<>();
    private static volatile boolean called;

    public static void enter(String hook, PlayerController c) {
        called = true;
        Player p = c == null ? null : c.getPlayer();
        if (p == null) return;
        List<String> hooks = WATCHED.get(p);
        if (hooks != null) synchronized (hooks) { hooks.add(hook); }
    }

    static void watch(Player p) { WATCHED.put(p, new ArrayList<>()); }

    static List<String> stop(Player p) {
        List<String> h = WATCHED.remove(p);
        return h == null ? new ArrayList<>() : h;
    }

    /** True once the patched PlayerControllerAi is loaded: the probe below calls a patched method on an AI seat. */
    static boolean patched() { return called; }
}
